window.SLIDE_TEXT["coronary-angiogram"] = {"1":"",
"2":"<ul><li>Objectives</li><li>Know what the gold standard is for diagnosing coronary atherosclerosis</li><li>Know what a coronary angiogram is</li><li>Indications for a coronary angiogram</li><li>Contraindications for coronary angiogram</li><li>Know what medications are held prior and following a coronary angiogram</li><li>Know the possible complications during a coronary angiogram</li><li>Know the two most common access sites</li><li>Know the pre-op prep for patients with a contrast dye allergy</li><li>Understand the concepts of a coronary CT angiogram</li><li>Understand the concepts of coronary calcium scoring and how it is interpreted</li></ul>",
"3":"<ul><li>Cardiac Catheterization</li><li>Gold standard in diagnosis of coronary atherosclerosis</li></ul>",
"4":"<ul><li>Coronary Angiogram Indications</li><li>Angina that significantly interferes with a patients lifestyle despite maximal tolerable medical therapy</li><li>Patients with high risk criteria on noninvasive testing</li><li>Atypical symptoms with equivocal findings on stress testing in whom a diagnosis needs to be established</li><li>New onset cardiomyopathy</li></ul>",
"5":"<ul><li>Coronary Angiogram Indications</li><li>Initial test:<ul><li>Following sudden cardiac arrest</li><li>Life threatening ventricular arrhythmia</li><li>New onset symptomatic heart failure</li><li>ACS (STEMI, NSTEMI, unstable angina)</li></ul></li></ul>",
"6":"<ul><li>Contraindications (relative)</li><li>Acute renal failure</li><li>Active gastrointestinal bleeding</li><li>Unexplained fever, which may be due to infection</li><li>Untreated active infection</li><li>Acute stroke</li><li>Severe anemia</li><li>Severe uncontrolled HTN</li><li>Severe symptomatic electrolyte imbalance</li><li>Severe systemic illness</li><li>Severe concomitant illness that drastically shortens life</li><li>Refusal of patient to consider definitive therapy such as PCI</li><li>Digitalis intoxication</li><li>Documented anaphylactic reaction to contrast dye</li><li>Severe peripheral artery disease limiting vascular access</li><li>Decompensated heart failure or acute pulmonary edema</li><li>Severe coagulopathy</li><li>Aortic valve endocarditis</li></ul>",
"7":"<ul><li>Heart Catheterization Pre-op</li><li>ACE-I, ARB, and diuretics may be held the morning of the procedure</li><li>Anticoagulation is held prior to procedure. INR must be &lt; 1.5</li><li>Metformin is held the day of and 48 hours following procedure</li><li>Nothing to eat or drink after midnight the night before</li><li>Patient is shaved and given a sedative to relax</li></ul>",
"8":"<ul><li>Methodology</li></ul>",
"9":"",
"10":"<ul><li>Obtain Access</li><li>Femoral</li><li>Radial</li><li>Brachial</li><li>Subclavian</li></ul>",
"11":"<ul><li>Femoral access must be no more than 3 cm below the inguinal ligament.</li><li>Too high and you are at risk for retroperitoneal bleed.</li><li>Too low and you are at risk for pseudo-aneursym</li></ul>",
"12":"<ul><li>Cannulation of Coronary Arteries</li></ul>",
"13":"<ul><li>Angiogram</li></ul>",
"14":"<ul><li>Percutaneous Coronary Intervention (PCI)</li><li>Stenosis of less than 70% are not flow-limiting and rarely require revascularization</li></ul>",
"15":"",
"16":"<ul><li>Sheath Removal</li><li>Sheath remains in place until anticoagulants are below their peak activation (Usually 4 hrs following the last dose of heparin)</li><li>Hourly vital signs</li><li>30 minute groin checks</li><li>Sheath is remove and pressure is applied to femoral artery simultaneously</li><li>Pressure is applied for approximately 20 mins or until hemostasis is obtained</li><li>Bedrest for 6 hours following</li></ul>",
"17":"<ul><li>Post-op</li><li>Vital signs:<ul><li>Every 15 mins for 1 hr</li><li>Every 30 mins for 3 hrs</li><li>Every 4 hours for 24 hrs</li></ul></li><li>No heavy lifting (&gt;10 lbs) for 1 week</li><li>No strenuous exercise for 1 week</li></ul>",
"18":"<ul><li>Hemostasis At Access Site</li><li>Hand held pressure</li><li>Mechanical clamp</li><li>Closure device</li></ul>",
"19":"<ul><li>Mynx Device</li></ul>",
"20":"<ul><li>TR Band</li></ul>",
"21":"<ul><li>https://www.youtube.com/watch?v=e13TGGccvT4</li></ul>",
"22":"<ul><li>Complications</li><li>Death (0.1%)</li><li>MI (0.1%)</li><li>Stroke (0.4% during PCI)</li><li>Vascular complications:<ul><li>Acute thrombosis/distal embolization</li><li>Dissection (acute)</li><li>Hematoma/hemorrhage (acute)</li><li>Pseudoaneurysm (late)</li><li>AV fistula (late)</li><li>Retroperitoneal hemorrhage</li></ul></li><li>Arrhythmia</li><li>Allergic reaction (iodine contrast agent)</li><li>Acute kidney injury</li></ul>",
"23":"<ul><li>Allergy To Contrast Dye</li><li>Prednisone 50 mg 13, 7, and 1 hour prior to procedure</li><li>Benadryl 50 mg 1 hour prior to procedure</li></ul>",
"24":"<ul><li>Right Heart Cath</li><li>Pulmonay artery catheters (Swan-Ganz catheters)</li><li>Direct measurements:<ul><li>Central venous pressure (CVP)</li><li>Right-sided intracardiac pressures</li><li>Pulmonary arterial pressure (Pap)</li><li>Pulmonary capillary occlusion pressure (PCOP)</li><li>Cardiac output (CO)</li><li>Mixed venous oxyhemoglobin saturation (SvO2)</li></ul></li></ul>",
"25":"<ul><li>Indications</li><li>Unexplained or unknown volume status in shock</li><li>Severe cardiogenic shock</li><li>Suspected or known pulmonary artery hypertension</li><li>Severe underlying cardiopulmonary disease (congenital heart disease, left-to-right shunt, severe valvular disease, pulmonary hypertension)</li></ul>",
"26":"<ul><li>Coronary CT Angiogram</li></ul>",
"27":"<ul><li>Coronary CT Angiography</li><li>Non-invasive coronary angiography</li><li>Indicated for patients who have intermediate risk factors with equivocal stress test results</li><li>Useful in patients with known or suspected congenital coronary anomalies.</li><li>Patient is typically given BB to slow down heart rate to 60-70 bpm, nitroglycerin for vasodilation and IV contrast dye</li></ul>",
"28":"<ul><li>Coronary CT Angiogram</li><li>Negative predictive value of 95-100% for significant CAD in multicenter studies</li><li>Positive predictive value 91-93% for left main disease and bypass grafts</li><li>Positive predictive value of 60-84% for other coronary arteries</li></ul>",
"29":"<ul><li>Limitations</li><li>Heart rate greater than 70 bpm</li><li>Irregular heart rhythm</li><li>Inability to hold breath for five seconds</li><li>Severe coronary calcification or prior stents</li></ul>",
"30":"<ul><li>Coronary Calcium Scoring</li><li>Screening tool for asymptomatic patients</li><li>Recommended for low-intermediate and intermediate risk patients</li><li>Predicts the extent of coronary atherosclerosis or plaque burden</li><li>CAN NOT measure severity of coronary stenosis</li><li>Highly predictive of the absence of coronary atherosclerosis</li></ul>",
"31":"<ul><li>Coronary Calcium Scoring</li><li>0 – no identifiable disease</li><li>1 to 99 – mild disease</li><li>100 to 399 – moderate disease</li><li>&gt;400 – severe disease</li></ul>",
"32":"<ul><li>References</li><li>1. \"Selecting the Optimal Cardiac Stress Test.\" UpToDate. 3 April 2014. Web. 26 Oct. 2015.</li><li>2. \"Overview of Stress Radionuclide Myocardial Perfusion Imaging.\" UpToDate. 13 April 2015. Web. 26 Oct. 2015.</li><li>3. \"Transesophageal Echocardiography: Indications, Complications, and Normal Views.\" UpToDate. 13 Aug 2015. Web. 26 Oct. 2015.</li><li>4. \"Overview of Stress Echocardiography.\" UpToDate. 20 Feb 2015. Web. 26 Oct. 2015.</li><li>5. \"Complications of Diagnostic Cardiac Catheterization.\" UpToDate. 29 April 2013. Web. 26 Oct. 2015.</li><li>6. \"Pulmonary Artery Catheterization: Indications, Contraindications, and Complications in Adults.\" UpToDate. 20 Aug. 2015. Web. 26 Oct. 2015.</li><li>7. \"Noninvasive Imaging and Stress Testing in Patients with Suspected Acute Coronary Syndrome.\" UpToDate. 245 April 2015. Web. 26 Oct. 2015.</li><li>8. \"Noninvasive Coronary Imaging with Cardiac Computed Tomography and Cardiovascular Magnetic Resonance.\" UpToDate. 17 March 2015. Web. 26 Oct. 2015.</li><li>9. \"Diagnostic and Prognostic Implications of Coronary Artery Calcification Detected by Computed Tomography.\" UpToDate. 25 Nov. 2014. Web. 26 Oct. 2015.</li><li>10. \"Noninvasive Methods for Measurement of Left Ventricular Systolic Function.\" UpToDate. 2 Feb. 2012. Web. 26 Oct. 2015.</li></ul>"};
